function Topics(){const {data,setModal,go,mutate}=useStudio();const [q,setQ]=useState(''),[status,setStatus]=useState('all'),[tag,setTag]=useState('all'),[time,setTime]=useState('all'),[min,setMin]=useState('all'),[favorite,setFavorite]=useState(false),[sort,setSort]=useState('score');const items=data.topics.filter(t=>(status==='all'||t.status===status)&&(tag==='all'||t.tags.includes(tag))&&(!favorite||t.favorite)&&(time==='all'||Date.now()-Date.parse(t.updated_at)<Number(time)*86400000)&&(min==='all'||(min==='missing'?(t.screening?.coverage??0)<60:(t.screening?.total??0)>=Number(min)))&&(!q||[t.title,t.question,t.angle,t.tags.join(' ')].join(' ').toLowerCase().includes(q.toLowerCase()))).sort((a,b)=>sort==='score'?(b.screening?.total??b.score.total??-1)-(a.screening?.total??a.score.total??-1):sort==='updated'?b.updated_at.localeCompare(a.updated_at):({'优先':2,'常规':1,'暂缓':0}[b.priority]-{'优先':2,'常规':1,'暂缓':0}[a.priority])||(b.screening?.total??b.score.total??-1)-(a.screening?.total??a.score.total??-1));return <><Head title="选题库" desc="管理选题、明确切入角度，并用 AI 推进脚本创作。" actions={<><Button onClick={()=>go('inbox')}>从素材创建</Button><Button primary icon="plus" onClick={()=>setModal({type:'topic'})}>记录自有选题</Button></>}/><div className="tabs">{['all','待验证','待选定','已入选','创作中','待发布','已归档'].map(s=><button key={s} className={status===s?'active':''} onClick={()=>setStatus(s)}>{s==='all'?'全部选题':s}<small>{s==='all'?data.topics.length:data.topics.filter(t=>t.status===s).length}</small></button>)}</div><div className="toolbar"><input aria-label="搜索选题" placeholder="搜索标题、用户问题、角度…" value={q} onChange={e=>setQ(e.target.value)}/><select aria-label="选题状态" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">全部状态</option>{data.constants.topic_statuses.map(s=><option key={s}>{s}</option>)}</select><select aria-label="选题标签" value={tag} onChange={e=>setTag(e.target.value)}><option value="all">全部标签</option>{[...new Set(data.topics.flatMap(t=>t.tags))].map(t=><option key={t}>{t}</option>)}</select><select aria-label="选题时间范围" value={time} onChange={e=>setTime(e.target.value)}><option value="all">全部时间</option><option value="7">近 7 天</option><option value="30">近 30 天</option></select><select aria-label="评分筛选" value={min} onChange={e=>setMin(e.target.value)}><option value="all">全部评分</option><option value="missing">数据较少</option><option value="80">80 分及以上</option><option value="60">60 分及以上</option></select><select aria-label="选题排序" value={sort} onChange={e=>setSort(e.target.value)}><option value="priority">优先级排序</option><option value="score">评分从高到低</option><option value="updated">最近更新</option></select><label className="check"><input type="checkbox" checked={favorite} onChange={e=>setFavorite(e.target.checked)}/>仅收藏</label></div><p className="result-count">{items.length} 条选题 · 综合评分为可解释的研判工具，不是爆款概率</p>{items.length?<div className="topic-list">{items.map(t=><article className="card topic-card" key={t.id}><div className="topic-score"><strong>{t.screening?.total??'—'}</strong><small>领域优先分 / 100</small></div><div className="topic-content"><div className="tag-row"><Tag color={t.status==='已入选'?'green':'blue'}>{t.status}</Tag><Tag>{t.category}</Tag><Tag color={t.verified?'green':'orange'}>{t.verified?'证据已核实':'待核实'}</Tag>{t.priority==='优先'&&<Tag color="orange">优先</Tag>}</div><h3><button className="text-link" onClick={()=>go('topic',t.id)}>{t.title}</button></h3><p>{t.question||'尚未明确目标用户问题'}</p><p className="angle-line">角度：{t.angle||'待补充'}</p><div className="tag-row">{t.tags.map(x=><Tag key={x}>{x}</Tag>)}</div><ScoreBreakdown score={t.screening}/><small className="next-step"><Icon name="arrow"/>{nextStep(t)}</small><div className="meta-line"><span>{t.evidence_count} 份参考素材</span><span>更新于 {date(t.updated_at)}</span></div></div><div className="topic-actions"><Button ghost aria-label={t.favorite?'取消收藏':'收藏选题'} onClick={()=>mutate('/topics/'+t.id,'PUT',{favorite:!t.favorite},'收藏状态已更新')}>{t.favorite?'★':'☆'}</Button><Button small danger onClick={()=>setModal({type:'remove-topic',id:t.id,seed:{title:t.title}})}>从选题库移除</Button></div></article>)}</div>:<div className="card"><Empty title="每个好选题，都有一个真实问题" desc="从收集箱引用素材，或手动创建一个候选。新选题默认为待验证。"><Button primary onClick={()=>setModal({type:'topic'})}>创建第一个候选</Button></Empty></div>}</>;}
function TopicDetail({id}){const {setModal,go,mutate}=useStudio(),[t,error]=useDetail('topics',id);if(error)return <Empty title="无法打开选题" desc={error}/>;if(!t)return <p>正在读取选题…</p>;return <><button className="breadcrumb" onClick={()=>go('topics')}>← 返回选题库</button><Head title={t.title} desc={`${t.audience||'待明确受众'} · ${t.status}`} actions={<><Button onClick={()=>setModal({type:'topic',id,seed:t})}>编辑选题</Button><Button primary onClick={()=>setModal({type:'decision',id,seed:{status:'已入选'}})}>确认入选</Button></>}/><div className="detail-layout"><div><section className="card detail-section"><div className="card-head"><h2>选题策划</h2><Tag color="green">{t.status}</Tag></div><div className="detail-body"><dl><dt>观众问题</dt><dd>{t.question||'请补充观众问题，让AI策划更准确'}</dd><dt>切入角度</dt><dd>{t.angle||'请补充具体演示或讲解角度'}</dd><dt>策划依据与待核实事项</dt><dd style={{whiteSpace:'pre-wrap'}}>{t.notes||'暂无记录'}</dd></dl><ScoreBreakdown score={t.screening}/></div></section><section className="card detail-section"><div className="card-head"><h2>视频文案提取</h2><Tag color="green">AI 创作参考</Tag></div><div className="detail-body"><p>先提取关联视频的口播文案，再生成脚本。AI 会读取最新提取结果，按来源引用。</p>{t.evidence.filter(r=>contentKind(r)==='video'||/bilibili\.com\/video\/|douyin\.com\/video\//.test(r.url)).map(r=><div key={r.id}><h3>{r.title}</h3><VideoTranscript id={r.id} initial={r.transcript||{}}/></div>)}{!t.evidence.some(r=>contentKind(r)==='video'||/bilibili\.com\/video\/|douyin\.com\/video\//.test(r.url))&&<p className="muted">当前选题没有关联视频，可在下方“参考素材与证据”关联视频素材。</p>}</div></section><TopicWorkflow key={t.id} topic={t} mutate={mutate}/><section className="card detail-section"><div className="card-head"><h2>参考素材与证据</h2><Button small onClick={()=>setModal({type:'evidence',id,seed:t})}>关联更多素材</Button></div><div className="detail-body">{t.evidence.map(r=><article key={r.id}><h3><button className="text-link" onClick={()=>setModal({type:'raw-detail',id:r.id})}>{r.title}</button></h3><p>{r.summary}</p><Link url={r.url}>查看原始来源</Link></article>)}{!t.evidence.length&&<p>尚未关联参考素材，生成时请注意核验事实。</p>}</div></section><section className="card detail-section"><div className="card-head"><h2>状态变更历史</h2></div><ol className="timeline">{t.history.map(h=><li key={h.id}><strong>{h.from_status||'新建'} → {h.to_status}</strong><p>{h.reason}</p><small>{date(h.created_at)}</small></li>)}</ol></section></div><aside><section className="card aside-section"><h3>创作进度</h3><p>{nextStep(t)}</p><div className="button-stack"><Button primary onClick={()=>setModal({type:'decision',id,seed:{status:'已入选'}})}>准备拍摄</Button><Button onClick={()=>setModal({type:'decision',id,seed:{status:'创作中'}})}>开始创作</Button><Button onClick={()=>setModal({type:'decision',id,seed:{status:'待发布'}})}>准备发布</Button><Button onClick={()=>setModal({type:'decision',id,seed:{status:t.status}})}>修改状态</Button><Button onClick={()=>setModal({type:'decision',id,seed:{status:'已归档'}})}>归档选题</Button><Button danger onClick={()=>setModal({type:'remove-topic',id,seed:{title:t.title}})}>从选题库移除</Button></div></section><section className="card aside-section"><h3>模型服务</h3><p>通过统一网关调用正常渠道。生成结果先预览，采用后再保存。</p><Button onClick={()=>go('models')}>查看 AI 服务</Button><Button onClick={()=>go('models')}>模型设置</Button></section><section className="card aside-section"><h3>事实核验</h3><p>{t.verified?'已标记人工核验':'尚未标记人工核验，请在发布前核实来源、版本和关键事实。'}</p><Button onClick={()=>setModal({type:'topic',id,seed:t})}>编辑与核验</Button></section></aside></div></>;}

function Sources(){const {data,setModal,mutate,collect,busy,notify}=useStudio();return <><Head title="信息源管理" desc="公开来源，独立运行；每一次新增、重复和失败都有记录。" actions={<><Button disabled={!!busy} onClick={()=>collect({platform:'RSSHub'})}>采集厂商订阅</Button><Button onClick={()=>setModal({type:'platform-import'})}>导入平台数据</Button><Button onClick={async()=>{try{const result=await api('/platform/legacy-preview');setModal({type:'platform-import',seed:result});}catch(error){notify(error.message);}}}>读取原一日榜</Button><Button onClick={()=>setModal({type:'logs'})}>采集日志</Button><Button primary icon="plus" onClick={()=>setModal({type:'source'})}>添加信息源</Button></>}/><div className="notice top-note">默认每 4 小时采集，单源可调整。服务启动后扫描到期来源；服务关闭期间不采集，重启后补扫。手动采集受 1 分钟冷却保护，失败可重试。</div><div className="source-grid">{[...data.sources].sort(platformFirst).map(s=><article className="card source-card" key={s.id}><div className="source-card-head"><span className="source-icon"><Icon name="signal"/></span><div><h3>{s.name}</h3><small>{sourceTypeLabels[s.type]||s.type}</small></div><Tag color={s.enabled?'green':''}>{s.enabled?'已启用':'已停用'}</Tag></div><p className="source-url">{s.url}</p>{s.type==='rsshub'&&<p className="platform-source-note">RSSHub · {data.constants.rsshub_presets?.find(p=>p.route===s.query)?.kind||'自定义订阅'}。{data.constants.rsshub_presets?.find(p=>p.route===s.query)?.note||'保留官网原始链接及发布日期，公共实例内容可能缓存。'}</p>}{s.type==='bilibili_ranking'&&<p className="platform-source-note">从官方配置读取全部UGC分区，或编辑指定科技数码、美食、知识等。近期综合动态榜，非一日新增榜；每区独立保存排名快照。</p>}{s.type==='douyin_daily'&&<p className="platform-source-note">支持全部24个行业，或编辑指定行业；近1日是平台统计口径，保留视频指数原始排序。</p>}{s.type==='xiaohongshu_index'&&<p className="platform-source-note">从360公开搜索收录中发现各领域笔记标题、摘要和原链接；不是站内实时榜，无互动量。检索词可编辑，结果可能较旧，原文可能需要登录。</p>}{s.type==='xiaohongshu_public'&&<p className="platform-source-note">DataXAPI无需登录的公开页面，每日快照，不触发付费API；保留读取时间和页面热度展示值，不冒称笔记或实时数据。</p>}{s.type==='xiaohongshu'&&<p className="platform-source-note">先请求公开入口，失败后尝试60s公开聚合；此前分别返回406和429。成功时标明实际提供方，失败不伪造结果。</p>}{s.query&&<p className="muted">检索：{s.query}</p>}<div className="source-facts"><div><small>采集频率</small><strong>每 {s.frequency_minutes} 分钟</strong></div><div><small>最近运行</small><strong>{date(s.last_run?.started_at)}</strong></div></div><div className="run-metrics"><span><b>{s.last_run?.new_count??0}</b>新增</span><span><b>{s.last_run?.duplicate_count??0}</b>重复</span><span><b>{s.last_run?.failed_count??0}</b>失败</span><Tag color={s.last_run?.status==='failed'?'red':s.last_run?.status==='success'?'green':'orange'}>{({success:'成功',failed:'失败',partial:'部分失败',running:'运行中'})[s.last_run?.status]||'尚未运行'}</Tag></div>{s.last_run?.error&&<div className="error-note">{s.last_run.error}</div>}<div className="card-actions"><Button small primary disabled={!s.enabled||!!busy} onClick={()=>collect(s.id)}>立即采集</Button><Button small onClick={()=>setModal({type:'source',id:s.id,seed:s})}>编辑</Button><Button small ghost onClick={()=>mutate('/sources/'+s.id,'PUT',{enabled:!s.enabled},s.enabled?'来源已停用':'来源已启用')}>{s.enabled?'停用':'启用'}</Button><Button small ghost onClick={()=>setModal({type:'logs',id:s.id})}>日志</Button></div></article>)}</div></>;}
function Search(){const {go,setModal}=useStudio();const [q,setQ]=useState(''),[result,setResult]=useState({raw:[],topics:[]}),[error,setError]=useState('');useEffect(()=>{let active=true;const timer=setTimeout(()=>api('/search?q='+encodeURIComponent(q)).then(r=>{if(active){setResult(r);setError('');}}).catch(e=>active&&setError(e.message)),200);return()=>{active=false;clearTimeout(timer);};},[q]);return <><Head title="全局搜索" desc="跨原始素材、用户问题、内容角度、标签和来源，找回判断依据。"/><div className="large-search"><Icon name="search"/><input autoFocus aria-label="全局搜索关键词" value={q} onChange={e=>setQ(e.target.value)} placeholder="输入关键词，例如：本地部署、办公、模型名称…"/></div>{error&&<div className="error-note">{error}</div>}<p className="result-count">{q?`${result.raw.length+result.topics.length} 条结果`:'输入关键词开始搜索'}</p><div className="card search-results">{result.topics.map(t=><button key={t.id} onClick={()=>go('topic',t.id)}><Tag color="green">选题库</Tag><div><h3>{t.title}</h3><p>{t.question||t.angle}</p></div><Tag>{t.status}</Tag><Icon name="arrow"/></button>)}{result.raw.map(r=><button key={r.id} onClick={()=>setModal({type:'raw-detail',id:r.id})}><Tag color="blue">收集箱</Tag><div><h3>{r.title}</h3><p>{r.summary}</p></div><small>{r.source_name||'手动录入'}</small><Icon name="arrow"/></button>)}{!result.raw.length&&!result.topics.length&&<Empty title={q?'没有匹配的内容':'素材与选题，都能找得到'} desc={q?'试试更短的关键词，归档选题也会被搜索。':'搜索结果标明模块，并直接打开原记录。'}/>}</div></>;}
function Settings(){const {data,mutate,setModal,notify,legacy}=useStudio();const [form,setForm]=useState(data.settings);const update=(k,v)=>setForm(f=>({...f,[k]:v}));const backup=async()=>{try{download(await api('/backup'),'张的工作台-数据库备份-'+new Date().toISOString().slice(0,10)+'.json');notify('完整备份已导出');}catch(e){notify(e.message);}};const importFile=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw new Error('备份文件不能超过 30MB');const parsed=JSON.parse(await file.text());if([1,2].includes(parsed.version)&&Array.isArray(parsed.topics)){setModal({type:'migrate',seed:parsed});return;}const counts=await api('/restore/validate','POST',parsed);setModal({type:'restore',seed:{data:parsed,counts}});}catch(error){notify(error.message);}finally{e.target.value='';}};return <><Head title="设置与使用说明" desc="本机持久化、公开采集、可选本地模型。每一步都留在你的掌控里。"/><div className="settings-layout"><form className="card settings-form" onSubmit={async e=>{e.preventDefault();const {model_provider,model_url,model_name,...preferences}=form;await mutate('/settings','PUT',preferences,'设置已保存，素材初筛与选题得分已按新权重重算');}}><h2>创作与采集偏好</h2><Text label="工作台名称" value={form.name} onChange={v=>update('name',v)} required/><Text label="目标受众" value={form.audience} onChange={v=>update('audience',v)} area required/><Text label="默认内容方向" value={form.directions} onChange={v=>update('directions',v)} area/><Text label="内容关键词" value={form.keywords} onChange={v=>update('keywords',v)} area help="逗号分隔，用于内容定位和模型提示，不限制公共来源的完整入库。"/><Text label="默认采集间隔（分钟）" value={form.frequency_minutes} type="number" min="30" max="10080" onChange={v=>update('frequency_minutes',Number(v))} help="新建来源使用此默认值；已有来源频率在信息源管理中单独修改。"/><label className="check"><input type="checkbox" checked={form.auto_collect} onChange={e=>update('auto_collect',e.target.checked)}/>服务运行时自动采集，启动时补扫到期来源</label><label className="check"><input type="checkbox" checked={form.auto_backup} onChange={e=>update('auto_backup',e.target.checked)}/>每次每日首次启动自动备份，保留最近 14 份</label><h2 className="section-divider">自动初筛权重 · 领域优先分</h2><p className="muted">总分100。缺少热度或发布时间时采用明确标注的中性先验，同时降低数据充分度；无关热点总分封顶25。</p><div className="weights">{(data.constants.screening_dimensions||[]).map(([k,label])=><Text key={k} label={label+'初筛权重（%）'} type="number" min="0" max="100" value={form.screening_weights[k]} onChange={v=>update('screening_weights',{...form.screening_weights,[k]:Number(v)})}/>)}</div><p className="muted">自动初筛权重合计 {Object.values(form.screening_weights||{}).reduce((a,b)=>a+b,0)}% · 保存后全库重算</p><h2 className="section-divider">RSSHub 厂商订阅</h2><Text label="RSSHub 实例地址" type="url" required value={form.rsshub_base_url} onChange={v=>update('rsshub_base_url',v)} help="默认使用已实测可用的公开实例。切换后统一更新所有RSSHub来源地址，路由和历史素材保留。每家订阅范围可在信息源卡片查看。"/><div className="form-submit"><Button primary type="submit">保存全部设置</Button></div></form><div><section className="card aside-section"><h2>本地数据与备份</h2><p>核心数据保存在本机 SQLite，不依赖浏览器缓存。关闭服务后停止采集，重启后继续。</p><code className="path">{data.storage.path}</code><p>备份目录</p><code className="path">{data.storage.backup_directory}</code><div className="button-stack"><Button primary icon="download" onClick={backup}>导出 JSON 完整备份</Button><Button onClick={()=>mutate('/backup/create','POST',{},'备份已保存至本机备份目录')}>另存一份本机备份</Button><label className="btn file-label">校验并恢复备份<input type="file" accept=".json,application/json" onChange={importFile}/></label><Button onClick={()=>{const escape=x=>'"'+String(/^[=+@-]/.test(String(x))?"'"+x:x??'').replace(/"/g,'""')+'"';download('\uFEFF'+[['标题','用户问题','角度','状态','评分','更新时间'],...data.topics.map(t=>[t.title,t.question,t.angle,t.status,t.score.total??'信息不足',t.updated_at])].map(row=>row.map(escape).join(',')).join('\r\n'),'选题库.csv','text/csv;charset=utf-8');}}>导出选题 CSV</Button></div><div className="notice">恢复会覆盖数据库内容；先校验并确认，恢复前自动另存完整备份。归档只改状态，不删除。</div></section><section className="card aside-section"><h2>旧版数据</h2><p>旧版浏览器数据支持人工确认迁移；原脚本、素材和复盘等内容完整另存，不覆盖原浏览器数据。</p>{legacy&&!data.legacy&&<Button onClick={()=>setModal({type:'migrate'})}>迁移此浏览器旧数据</Button>}{!!data.legacy&&<Button onClick={async()=>{try{const records=await api('/legacy');download(records,'旧版完整数据存档.json');}catch(e){notify(e.message);}}}>导出已保留的旧版完整数据</Button>}</section><section className="card aside-section"><h2>使用顺序</h2><ol className="help-list"><li>启用来源，手动采集或等待定时扫描。</li><li>在收集箱查看原文、整理摘要与标签。</li><li>人工选择角度，创建待验证候选。</li><li>系统带入初评和依据；按需复核或请求本地 AI 深度评估。</li><li>核验来源后，人工确认入选；也可放弃或归档。</li></ol><p>评分不足时不生成完整分数。GitHub stars、模型下载量是各自平台的快照，不等于增长趋势或抖音流量。</p><p>本版不提供自动视频制作、抖音登录或自动发布。</p></section></div></div></>;}
function Modal(){const {modal,setModal,busy}=useStudio();const close=()=>setModal(null),dialogRef=useRef();useEffect(()=>{const before=document.activeElement;const first=dialogRef.current?.querySelector('input,textarea,select,button');first?.focus();const handler=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focus=[...dialogRef.current.querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0]?.focus();}}};document.body.style.overflow='hidden';window.addEventListener('keydown',handler);return()=>{document.body.style.overflow='';window.removeEventListener('keydown',handler);before?.focus?.();};},[]);const titles={'remove-topic':'从选题库移除',raw:'原始素材',topic:modal.id?'编辑选题':'创建候选选题',scores:'六维评分与依据',decision:'人工决策与状态',source:modal.id?'编辑信息源':'添加公开信息源',logs:'采集运行日志','raw-detail':'原始素材详情','raw-state':'素材处理记录',evidence:'关联参考素材',restore:'确认恢复备份',migrate:'迁移旧版数据','platform-import':'导入平台榜单与笔记'};return <div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)close();}}><section ref={dialogRef} className={'modal '+(['raw-detail','topic','scores','logs'].includes(modal.type)?'wide':'')} role="dialog" aria-modal="true" aria-labelledby="modal-heading"><header><h2 id="modal-heading">{titles[modal.type]||'详情'}</h2><Button ghost icon="close" aria-label="关闭对话框" onClick={close}/></header><div className="modal-content">{modal.type==='remove-topic'?<RemoveTopic/>:modal.type==='raw'?<RawEditor/>:modal.type==='topic'?<TopicEditor/>:modal.type==='scores'?<ScoreEditor/>:modal.type==='decision'?<Decision/>:modal.type==='source'?<SourceEditor/>:modal.type==='logs'?<Logs/>:modal.type==='raw-detail'?<RawDetail/>:modal.type==='raw-state'?<RawState/>:modal.type==='evidence'?<EvidenceEditor/>:modal.type==='restore'?<Restore/>:modal.type==='migrate'?<Migrate/>:modal.type==='platform-import'?<PlatformImport/>:null}</div></section></div>;}
function FormActions({label='保存',disabled=false}){const {setModal}=useStudio();return <div className="form-actions"><Button onClick={()=>setModal(null)}>取消</Button><Button primary type="submit" disabled={disabled}>{label}</Button></div>;}
function RawEditor(){const {modal,data,mutate,setModal}=useStudio(),r=modal.seed||data.raw.find(x=>x.id===modal.id)||{};const [form,setForm]=useState({title:r.title||'',url:r.url||'',summary:r.summary||'',tags:r.tags?.join('，')||'',notes:r.notes||''});const update=(k,v)=>setForm(f=>({...f,[k]:v}));return <form onSubmit={async e=>{e.preventDefault();const payload={...form,tags:splitTags(form.tags)};const result=await mutate(modal.id?'/raw/'+modal.id:'/raw',modal.id?'PUT':'POST',payload,'素材已保存');if(result)setModal(null);}}><Text label="素材标题" value={form.title} onChange={v=>update('title',v)} required/><Text label="原始链接" type="url" value={form.url} onChange={v=>update('url',v)} disabled={!!modal.id} help={modal.id?'已采集的原始链接保持不变。':'可留空，但会标记缺少链接。'}/><Text label="摘要" value={form.summary} area onChange={v=>update('summary',v)}/><Text label="标签（逗号分隔）" value={form.tags} onChange={v=>update('tags',v)}/><Text label="整理与核验备注" value={form.notes} area onChange={v=>update('notes',v)}/><FormActions/></form>;}
function TopicEditor(){const {modal,data,mutate,setModal,go}=useStudio(),t=modal.seed||{};const [form,setForm]=useState({title:t.title||'',question:t.question||'',angle:t.angle||'',audience:t.audience||data.settings.audience,category:t.category||'工具教程',priority:t.priority||'常规',verified:!!t.verified,cost:t.cost||'',notes:t.notes||'',tags:t.tags?.join('，')||'',evidence_ids:t.evidence_ids||t.evidence?.map(x=>x.id)||[]});const update=(k,v)=>setForm(f=>({...f,[k]:v}));return <form onSubmit={async e=>{e.preventDefault();const result=await mutate(modal.id?'/topics/'+modal.id:'/topics',modal.id?'PUT':'POST',{...form,tags:splitTags(form.tags),apply_rule_scores:false},modal.id?'选题已更新':'候选已创建，状态为待验证');if(result){setModal(null);go('topic',result.id);}}}><Text label="选题标题" value={form.title} onChange={v=>update('title',v)} required/><Text label="目标用户问题" value={form.question} onChange={v=>update('question',v)} placeholder="观众具体需要解决什么问题？"/><Text label="内容切入角度" area value={form.angle} onChange={v=>update('angle',v)}/><Text label="目标受众" value={form.audience} onChange={v=>update('audience',v)}/><div className="form-grid"><Select label="内容方向" value={form.category} onChange={v=>update('category',v)} options={['教程指南','案例分析','热点解读','对比测评','经验分享','知识科普','行业动态','深度观点']}/><Select label="优先级" value={form.priority} onChange={v=>update('priority',v)} options={['优先','常规','暂缓']}/></div><Text label="标签（逗号分隔）" value={form.tags} onChange={v=>update('tags',v)}/><Text label="预计制作成本" value={form.cost} onChange={v=>update('cost',v)} placeholder="时间、所需录屏与测试、是否有费用"/><Text label="研判备注 / 不确定性 / 额外来源" area value={form.notes} onChange={v=>update('notes',v)}/><h3 className="form-subhead">关联原始素材（可多选）</h3><div className="evidence-picker">{data.raw.length?data.raw.map(r=><label key={r.id}><input type="checkbox" checked={form.evidence_ids.includes(r.id)} onChange={e=>update('evidence_ids',e.target.checked?[...form.evidence_ids,r.id]:form.evidence_ids.filter(x=>x!==r.id))}/><span>{r.title}<small>{r.source_name||'手动'} · {r.status}</small></span></label>):<p className="muted">收集箱暂无素材，可先保存候选，之后补充证据。</p>}</div><label className="check"><input type="checkbox" checked={form.verified} onChange={e=>update('verified',e.target.checked)}/>我已人工核实来源、关键事实、版本和时间</label><div className="notice">新建候选默认为待验证。创建后可整理脚本、复制提示词，并决定是否准备拍摄。</div><FormActions label={modal.id?'保存选题':'创建候选'}/></form>;}
function ScoreEditor(){const {data,modal,mutate,setModal}=useStudio(),t=modal.seed;const [scores,setScores]=useState(data.constants.dimensions.map(([dimension])=>({dimension,value:t.score.current[dimension]?.value??'',reason:t.score.current[dimension]?.reason||''})));const update=(dimension,key,value)=>setScores(scores.map(x=>x.dimension===dimension?{...x,[key]:value}:x));return <form onSubmit={async e=>{e.preventDefault();const result=await mutate('/topics/'+modal.id+'/scores','POST',{scores:scores.map(s=>({...s,value:s.value===''?null:Number(s.value)}))},'人工评分与依据已记录，之前的评分历史保留');if(result)setModal(null);}}><div className="notice">每项 0–5 分并填写依据。没有证据请选择“信息不足”；不必为了入选而凑分。此处保留旧六维人工研判。素材初筛采用独立五项优先分，无需逐项填写。</div>{data.constants.dimensions.map(([key,label])=>{const s=scores.find(x=>x.dimension===key);return <div className="score-editor-row" key={key}><Select label={`${label}（${data.settings.weights[key]}%）`} value={s.value} onChange={v=>update(key,'value',v)} options={[["",'信息不足'],...Array.from({length:6},(_,i)=>[String(i),String(i)+' 分'])]}/><Text label={label+'评分理由'} area required value={s.reason} onChange={v=>update(key,'reason',v)} placeholder={key==='heat'?'引用来源链接和实际热度/累计数据；不把快照说成增长趋势。没有数据请说明信息不足。':'记录证据、具体判断与不确定性。'}/></div>;})}<FormActions label="保存六维评分"/></form>;}
function RemoveTopic(){const {modal,mutate,go,setModal}=useStudio();return <><p>确定将“{modal.seed?.title}”从选题库移除？</p><div className="notice">收集箱素材、原始链接、采集数据均保留。若素材不再关联其他选题，会回到“已整理”，可再次用于新选题。</div><div className="form-actions"><Button onClick={()=>setModal(null)}>取消</Button><Button danger onClick={async()=>{if(await mutate('/topics/'+modal.id,'DELETE',{},'已从选题库移除，收集箱素材保留'))go('topics');}}>确认移除</Button></div></>;}
function Decision(){const {modal,data,mutate,setModal}=useStudio();const [status,setStatus]=useState(modal.seed?.status||'待验证'),[reason,setReason]=useState('');return <form onSubmit={async e=>{e.preventDefault();const result=await mutate('/topics/'+modal.id+'/status','POST',{status,reason},'状态已更新，历史已记录');if(result)setModal(null);}}><Select label="目标状态" value={status} onChange={setStatus} options={data.constants.topic_statuses}/><Text label="决策原因（可选）" value={reason} onChange={setReason} area placeholder="为什么值得做、还缺什么证据，或为什么暂缓 / 放弃？"/><div className="notice">入选由你决定，无需填写旧六维评分。未核验来源会继续提醒；归档与放弃保留记录。</div><FormActions label="确认状态变更"/></form>;}
function SourceEditor(){const {modal,data,mutate,setModal}=useStudio(),s=modal.seed||{};const [form,setForm]=useState({name:s.name||'',type:s.type||'rss',url:s.url||'',query:s.query||'',frequency_minutes:s.frequency_minutes||data.settings.frequency_minutes,enabled:s.enabled??1});const update=(k,v)=>setForm(f=>({...f,[k]:v}));const isPlatform=data.constants.platform_presets.some(x=>x.type===form.type);return <form onSubmit={async e=>{e.preventDefault();const result=await mutate(modal.id?'/sources/'+modal.id:'/sources',modal.id?'PUT':'POST',form,'来源配置已保存');if(result)setModal(null);}}><Text label="来源名称" required value={form.name} onChange={v=>update('name',v)}/><Select label="来源类型" value={form.type} onChange={v=>{if(v==='rsshub'){const p=data.constants.rsshub_presets[0];setForm(f=>({...f,type:v,name:f.name||p.vendor+' · '+p.kind,query:p.route,url:data.settings.rsshub_base_url+p.route}));return;}const preset=data.constants.platform_presets.find(x=>x.type===v);setForm(f=>({...f,type:v,url:preset?.url||(v==='github'?'https://api.github.com/search/repositories':v==='huggingface'?'https://huggingface.co/api/models':''),query:preset?.query||'',frequency_minutes:preset?.frequency_minutes||f.frequency_minutes}));}} options={Object.entries(sourceTypeLabels)}/><Text label="公开地址" type="url" required disabled={isPlatform||form.type==='rsshub'} value={form.url} onChange={v=>update('url',v)}/>{['rsshub','github','huggingface','douyin_daily','bilibili_ranking','xiaohongshu_index'].includes(form.type)&&<Text label={form.type==='xiaohongshu_index'?'笔记线索检索词（逗号分隔）':form.type==='rsshub'?'RSSHub 路由':form.type==='github'?'GitHub 搜索语句':form.type==='bilibili_ranking'?'排行榜分区（逗号分隔）':form.type==='douyin_daily'?'一日榜垂类（逗号分隔）':'模型任务类型'} value={form.query} onChange={v=>update('query',v)} placeholder={form.type==='github'?'topic:llm stars:>100':['douyin_daily','bilibili_ranking','xiaohongshu_index'].includes(form.type)?'全部':'text-generation'} help={form.type==='xiaohongshu_index'?'最多24个检索词，覆盖不同领域；关键词是检索范围，不代表平台官方行业分类。每次每词读取前2页，间隔1.5秒。':form.type==='rsshub'?'例如 /anthropic/news。实例地址在设置中统一修改；官网新闻与官方开源仓库动态是不同内容范围。':form.type==='bilibili_ranking'?'默认全部UGC分区；可填科技数码,美食,知识或官方分区ID。番剧、电影等PGC榜不混入视频分区榜。':form.type==='douyin_daily'?'默认“全部”采集24个行业；也可填美食,汽车,财经等，串行请求至少间隔1.5秒。':undefined}/>}<Text label="采集间隔（分钟）" type="number" min="30" max="10080" value={form.frequency_minutes} onChange={v=>update('frequency_minutes',Number(v))} required/><label className="check"><input type="checkbox" checked={!!form.enabled} onChange={e=>update('enabled',e.target.checked)}/>启用该来源</label><div className="notice">只请求公开来源，不启动登录浏览器或复用他人会话。小红书返回权限或风控错误时保留错误记录，支持文件导入。定时采集不会执行原 run_reports.py 或 Excel / 飞书流程。</div><FormActions label="保存来源"/></form>;}

function Logs(){const {data,modal,collect,busy}=useStudio();const runs=data.runs.filter(r=>!modal.id||r.source_id===modal.id);return <div className="logs">{runs.length?runs.map(r=><article key={r.id}><div className="log-head"><h3>{r.source_name}</h3><Tag color={r.status==='success'?'green':r.status==='running'?'blue':'red'}>{({success:'成功',running:'运行中',failed:'失败',partial:'部分失败'})[r.status]}</Tag></div><p>开始 {date(r.started_at)} → 结束 {date(r.finished_at)} · {r.trigger==='scheduled'?'自动调度':r.trigger==='import'?'文件导入':'手动触发'}</p><div className="tag-row"><Tag>获取 {r.fetched_count}</Tag><Tag color="green">新增 {r.new_count}</Tag><Tag>重复 {r.duplicate_count}</Tag><Tag color={r.failed_count?'red':''}>失败 {r.failed_count}</Tag></div>{r.error&&<p className="error-note">{r.error}</p>}{r.source_id&&<Button small disabled={!!busy} onClick={()=>collect(r.source_id)}>重新采集</Button>}</article>):<Empty title="还没有运行记录" desc="触发一次采集后，可以在这里查看新增、重复和错误原因。"/>}</div>;}
function RawDetail(){const {modal,data,setModal,go,analyze,busy,mutate}=useStudio(),[r,error]=useDetail('raw',modal.id);if(error)return <p>{error}</p>;if(!r)return <p>正在读取原始记录…</p>;return <><div className="tag-row"><Tag color="blue">{r.source_name||'手动录入'}</Tag><Tag>{r.content_type}</Tag><Tag color="orange">{r.status}</Tag></div><h2 className="raw-detail-title">{r.title}</h2><Link url={r.url}>打开原始链接</Link><dl className="raw-dl"><dt>发布时间</dt><dd>{date(materialTime(r).value)}{materialTime(r).fallback?'（来源未提供有效发布时间，使用入库时间代替）':''}</dd><dt>采集 / 入库时间</dt><dd>{date(r.created_at)}</dd><dt>摘要</dt><dd>{r.summary||'未提供，可手动补充'}</dd><dt>标签</dt><dd>{r.tags.join('、')||'暂无'}</dd><dt>可用数据快照</dt><dd>{r.metrics?.platform?<MetricBlock metrics={r.metrics}/>:Object.keys(r.metrics).length?JSON.stringify(r.metrics,null,2):'来源未提供热度数据，不会虚构。'}</dd></dl><div className="actions wrap"><Button primary onClick={async()=>{const result=await mutate('/topics','POST',{title:r.title,tags:r.tags,evidence_ids:[r.id]},'已加入选题库');if(result)go('topic',result.id);}}>一键加入选题库</Button></div>{r.ai_result&&<section className="ai-result raw-ai"><h3>AI 建议 · 人工确认后采用</h3><p>{r.ai_result.summary}</p><p>不确定性：{r.ai_result.uncertainty||'模型未补充，请自行核查。'}</p><small>{r.ai_result.model} · {date(r.ai_result.generated_at)}</small><div className="actions"><Button small onClick={()=>setModal({type:'raw',id:r.id,seed:{...r,summary:r.ai_result.summary,tags:r.ai_result.tags}})}>检查并采用摘要</Button></div>{r.ai_result.angles?.map((a,i)=><div className="angle-proposal" key={i}><h3>{a.title}</h3><p>{a.question} · {a.angle}</p><Button small onClick={()=>setModal({type:'topic',seed:{...a,evidence_ids:[r.id]}})}>确认这个候选角度</Button></div>)}</section>}<h3 className="form-subhead">榜单与指标历史快照</h3>{r.snapshots?.length?<details className="platform-snapshots"><summary>{r.snapshots.length} 条快照 · 跨日期 / 垂类独立保存</summary>{r.snapshots.map(s=><div key={s.id}><MetricBlock metrics={s.metrics}/><small>{s.metrics.note}</small></div>)}</details>:<p className="muted">暂无平台快照。普通资讯不虚构互动指标。</p>}<h3 className="form-subhead">处理记录</h3><div className="raw-history">{r.history.map(h=><div key={h.id}><strong>{h.action}</strong><p>{h.reason}</p><small>{date(h.created_at)}</small></div>)}</div><Button danger small onClick={()=>setModal({type:'raw-state',id:r.id,seed:{delete:true}})}>永久删除原始素材</Button></>;}
function RawLinker({raw}){const {data,mutate}=useStudio();const [target,setTarget]=useState('');return <div className="inline-form"><select aria-label="关联另一条素材" value={target} onChange={e=>setTarget(e.target.value)}><option value="">选择另一条素材…</option>{data.raw.filter(x=>x.id!==raw.id).map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select><Button small disabled={!target} onClick={()=>mutate('/raw-link','POST',{left_id:raw.id,right_id:target,reason:'人工确认关联相同或相关事件'},'已关联，两个原始记录均保留')}>关联保留</Button></div>;}
function RawState(){const {modal,mutate,setModal}=useStudio();const [reason,setReason]=useState('');return <form onSubmit={async e=>{e.preventDefault();const result=await mutate('/raw/'+modal.id,modal.seed?.delete?'DELETE':'PUT',modal.seed?.delete?{}:{status:modal.seed.status,reason},modal.seed?.delete?'素材已永久删除；选题记录保留':'处理状态已记录');if(result)setModal(null);}}><div className={modal.seed?.delete?'error-note':'notice'}>{modal.seed?.delete?'永久删除无法撤销，会解除与选题的证据关联。建议先导出备份；忽略操作可保留全部记录。':'将素材设为“'+modal.seed.status+'”，保留处理历史。'}</div><Text label="处理原因" area value={reason} onChange={setReason}/><FormActions label={modal.seed?.delete?'确认永久删除':'确认处理'}/></form>;}
function EvidenceEditor(){const {modal,data,mutate,setModal}=useStudio();const [ids,setIds]=useState(modal.seed.evidence.map(x=>x.id));return <form onSubmit={async e=>{e.preventDefault();const result=await mutate('/topics/'+modal.id,'PUT',{evidence_ids:ids},'参考素材已关联');if(result)setModal(null);}}><p className="muted">一条素材可支持多个选题，一个选题可关联多个独立来源。</p><div className="evidence-picker tall">{data.raw.map(r=><label key={r.id}><input type="checkbox" checked={ids.includes(r.id)} onChange={e=>setIds(e.target.checked?[...ids,r.id]:ids.filter(x=>x!==r.id))}/><span>{r.title}<small>{r.source_name||'手动'}</small></span></label>)}</div><p className="muted">此操作添加所选关联，保留已有证据，避免误删判断依据。</p><FormActions label="保存证据关联"/></form>;}
function Restore(){const {modal,mutate,setModal}=useStudio(),{counts,data}=modal.seed;return <><div className="error-note">恢复会覆盖当前 SQLite 数据库。恢复前自动保存一份完整备份，恢复出错时数据库事务回滚。</div><p className="confirm-copy">即将恢复 {counts.raw} 条素材、{counts.topics} 个选题、{counts.sources} 个信息源。</p><div className="form-actions"><Button onClick={()=>setModal(null)}>取消</Button><Button primary onClick={async()=>{const result=await mutate('/restore','POST',data,'数据库已恢复，恢复前备份：');if(result)setModal(null);}}>确认覆盖并恢复</Button></div></>;}
function Migrate(){const {modal,legacy,mutate,setModal,setLegacy}=useStudio(),data=modal.seed||legacy;return <><div className="notice">将旧版灵感、热点和候选导入 SQLite，不清除浏览器原数据；旧脚本、素材与复盘的完整 JSON 另存存档。旧版评分不符合新六维规则，不自动转成入选。</div><p className="confirm-copy">检测到 {data?.topics?.length||0} 个选题、{data?.inbox?.length||0} 条灵感、{data?.scripts?.length||0} 份脚本。</p><div className="form-actions"><Button onClick={()=>setModal(null)}>暂不迁移</Button><Button primary onClick={async()=>{const result=await mutate('/migrate','POST',data,'旧版内容已迁移，原脚本等已完整存档');if(result){setModal(null);setLegacy(null);}}}>确认迁移并保留原数据</Button></div></>;}

function PlatformImport(){const {modal,setModal,notify,mutate,go}=useStudio();const [platform,setPlatform]=useState(modal.seed?.platform||'douyin_daily'),[text,setText]=useState(modal.seed?JSON.stringify(modal.seed.payload):''),[preview,setPreview]=useState(modal.seed||null),[busy,setBusy]=useState(false);const parse=async()=>{setBusy(true);try{const payload=JSON.parse(text);const result=await api('/platform/import-preview','POST',{platform,payload});setPreview({...result,payload});}catch(error){notify('校验失败：'+error.message);}finally{setBusy(false);}};return <><div className="notice">只读取你选择的 JSON，不运行旧报告脚本。统计日期和采集日期原样保存；旧榜单明确标为历史快照。文件中的平台指标不代表本次联网抓取。</div><Select label="导入平台与格式" value={platform} onChange={v=>{setPlatform(v);setPreview(null);}} options={[["douyin_daily","抖音创作指南一日榜 · 原项目 JSON"],["douyin","抖音实时热榜 JSON"],["bilibili","B站热门接口 JSON"],["xiaohongshu","小红书热榜 / 本人导出笔记 JSON"]]}/><label className="btn file-label">选择 JSON 文件<input type="file" accept=".json,application/json" onChange={async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){notify('文件不能超过20MB');return;}setText(await file.text());setPreview(null);}}/></label><Text label="榜单 / 笔记 JSON" area value={text} onChange={v=>{setText(v);setPreview(null);}} placeholder='粘贴已有榜单 JSON，小红书笔记可用 {"platform":"小红书","collected":"...","items":[{"title":"...","url":"https://www.xiaohongshu.com/explore/...","likes":12}]}'/><Button onClick={parse} disabled={!text||busy}>{busy?'校验中…':'校验并预览'}</Button>{preview&&<div className="import-preview"><h3>可导入 {preview.count} 条记录</h3><p>{preview.stats_date?'统计日期：'+preview.stats_date:'来源未统一提供统计日期'} · 采集时间：{preview.collected||'未提供（仅记导入时间）'}</p>{preview.preview?.map((r,i)=><article key={i}><h3>{r.title}</h3><MetricBlock metrics={r.metrics}/></article>)}<div className="form-actions"><Button onClick={()=>setModal(null)}>取消</Button><Button primary onClick={async()=>{const result=await mutate('/platform/import','POST',{platform,payload:preview.payload},'平台数据已导入，原来源与日期保留');if(result){setModal(null);go('inbox');notify(`导入完成：新增 ${result.added}，重复 ${result.duplicates}；跨榜快照分别保存`);}}}>确认导入收集箱</Button></div></div>}</>;}

function ScoreBreakdown({score,preliminary=false}){if(!score?.contributions)return null;const modern=score.version===2;return <details className="score-breakdown"><summary><span>{modern?'领域优先分':preliminary?'旧六维规则初筛':score.complete?'六维加权得分':'人工研判进度'}</span><strong>{score.total??score.known_total}<small> / 100</small></strong><em>{modern?`${score.recommendation} · ${score.confidence} ${score.coverage}%`:score.complete?'当前权重计算':`已知贡献 · 覆盖 ${score.coverage}%`}</em></summary><div className="score-breakdown-body">{Object.entries(score.contributions).map(([key,c])=><div key={key}><span>{c.label}{c.estimated?' · 估计':''}</span><b>{c.excluded?'不计入':c.value===null?'信息不足':`${c.value} / 5 × ${c.weight}% = ${c.points}分`}</b><p>{c.reason}</p></div>)}{score.adjustment&&<p className="score-disclaimer">加权原分 {score.base_total} → 最终 {score.total}：{score.adjustment}</p>}<p className="score-disclaimer">{modern?score.explanation:score.complete?'按当前保存的权重计算；人工评分优先于AI与规则初筛。':`缺失：${score.missing.map(key=>score.contributions[key].label).join('、')}。已知贡献不是完整总分。`}</p></div></details>;}
function WeightPreview({weights}){const {data}=useStudio();const [values,setValues]=useState({value:4,heat:3,visual:5,difference:2,timely:4,cost:3});const sum=Object.values(weights).reduce((n,v)=>n+v,0),score=data.constants.dimensions.reduce((n,[key])=>n+values[key]/5*(Number(weights[key])||0),0);return <section className="weight-preview"><div><h3>权重即时试算</h3><Tag>示例，不写入数据</Tag></div><p>调整上方权重或下方示例分数，查看每项贡献变化。保存后，收集箱初筛和选题综合分会使用新权重。</p><div className="weight-preview-rows">{data.constants.dimensions.map(([key,label])=><label key={key}><span>{label}</span><input aria-label={label+'示例分数'} type="number" min="0" max="5" step="1" value={values[key]} onChange={e=>setValues(v=>({...v,[key]:Math.max(0,Math.min(5,Number(e.target.value)))}))}/><span> / 5 × {weights[key]}%</span><strong>= {Math.round(values[key]/5*weights[key]*100)/100}分</strong></label>)}</div><footer>示例综合分 <strong>{Math.round(score*10)/10}</strong><small>/100</small>{sum!==100&&<em>当前权重合计{sum}%，请调整到100%后保存。</em>}</footer></section>;}
